-- 日期：2026-11-17　数据源：国家企业信用信息公示系统、北京市经开区与亦庄国投官网、公司融资公告、行业媒体
update research_companies set
  data = '{"ipo": {"date": "—", "board": "—", "raise": "—", "status": "未启动", "target": "—", "sponsors": "—", "structure": "境外平台 Pingu Tech Limited 经华封集芯（北京）科技发展 100% 持股", "preIpoValuation": "未披露（A 轮粗算投后约 45.5 亿元）"}, "seg": "osat", "code": "—", "desc": "国产版 EMIB 路线：自研「华封桥」桥接芯片 + 2.5D/3D Chiplet 封装集成，北京经开区 142 亩基地已实现 Bumping→FCBGA/FCCSP→FT 全链条通线量产（2026-09 公司口径），客户未披露。", "name": "华封集芯", "note": "未上市。33.2 亿总投资对应 5.37 亿注册资本，杠杆极高，依赖 23 亿银团贷款还本付息；客户、良率、单月产出三项零披露，「通线量产」尚不等于「规模量产」。与池内「华封科技」（Capcon，贴片设备）是两家不同公司。", "tech": [{"date": "2021-04", "kind": "公司", "title": "北京华封集芯电子有限公司成立，北京经开区引进，法定代表人张长海"}, {"date": "2023-09", "kind": "资本", "title": "完成天使轮，水木投资基金、海盈企业发展入股"}, {"date": "2024-01", "kind": "治理", "title": "法定代表人变更为李宗芳，主要管理人员整体更换"}, {"date": "2024-06", "kind": "资本", "title": "北京市与经开区三只政府基金入股（亦庄国投、京国瑞、北京集成电路基金），补齐北京先进封装环节"}, {"date": "2025", "kind": "资本", "title": "23 亿元银团贷款签约，农行牵头、7 家银行参与，投向 FCBGA、高密度 Bumping 与 2.5D/3D 产线"}, {"date": "2025-07", "kind": "布局", "title": "全资子公司杭州华封集芯成立，注册资本 500 万元，法定代表人姚远"}, {"date": "2026-01", "kind": "资本", "title": "3 亿元 A 轮交割（2 月官宣），北京高精尖基金领投，溥泉资本、智微资本、中创聚源、广发信德、纳川资本参与"}, {"date": "2026", "kind": "产能", "title": "亦庄基地进入竣工验收，规划 12 英寸 54 万片/年、达产 2,500 人"}, {"date": "2026-09", "kind": "产能", "title": "公司披露已实现 Bumping、FCBGA/FCCSP 至 FT 全链条先进封装测试通线量产；累计专利 46 项、商标 26 个"}], "round": "A 轮", "detail": "【定位】北京华封集芯电子有限公司，2021-04-06 成立，注册地北京经济技术开发区荣昌东街甲 5 号，注册资本 53,686.9129 万元（约 5.37 亿元）。是北京市集成电路「强链补链」项目中专门补先进封装缺口的一环——在此之前，北京的产业链有设计（集创北方、豪威）、制造（中芯北方、燕东）、设备（北方华创），唯独缺后道高端封装。\n【技术路线：为什么叫「国产版 EMIB」】它不做 CoWoS 式的硅中介层（Interposer），而是走 Intel EMIB 那条路——用一颗嵌入基板的硅桥（Bridge）把相邻两颗 die 在局部高速互连，其余区域用常规基板。这条路线的好处是不需要大面积硅中介层，成本与良率压力都低一档；代价是桥芯片本身要自研、且封装精度要求极高。公司自研的「华封桥」架构就落在这里，也是它区别于纯封测代工厂的地方：向上延伸到了桥接芯片设计，形成「芯片设计 + 封装集成」的双向能力。业务覆盖 Bumping（含晶圆清洗、RDL、凸块电镀）、FCBGA/FCCSP、2.5D/3D 集成、FT 成品测试、多物理场仿真与失效分析。\n【产能与投资：33 亿的钱从哪来】北京经开区基地占地 142 亩，总投资 33.2153 亿元。规划年产能：FCBGA 封测 7,200 万颗、FCCSP 3.82 亿颗、BUMPING 14 万片、WB 1 万片，折合 12 英寸晶圆 54 万片/年；完全达产带动 2,500 人就业，其中研发工程师 450 人。资金来源是三段拼起来的：① 2025 年 23 亿元银团贷款，中国农业银行牵头，邮储、建行、中行等 7 家参与，全部投向厂房、FCBGA 平台、高密度 Bumping 与 2.5D/3D 产线；② 2026 年 A 轮 3 亿元股权融资；③ 北京市与经开区两级政府基金的天使轮投入（北京集成电路产业基金、经开区产业升级基金、京国管基金）。这是一套典型的「政府基金做资本金 + 银团做重资产 + 产业资本做背书」结构。\n【进度：通线量产 ≠ 规模量产】2026 年内基地进入竣工验收并实现首批客户量产交付；2026-09 公司党支部书记李宗芳在亦庄国投联合党建活动中表述为「已实现 Bumping、FCBGA/FCCSP 至 FT 全链条先进封装测试通线量产」。这句话要拆开看：通线（整条流程跑通）已经做到，但客户名单、单月产出、良率三项均未披露。截至 2026 年参保人数 133 人，相对 2,500 人的达产规划仍在早期。\n【股东与管理层：董事长不持股，实权在 CEO】股东为华封集芯（北京）科技发展有限公司（由 Pingu Tech Limited 100% 持股的境外平台）、北京集成电路产业发展股权投资基金、北京经开区产业升级股权投资基金、北京京国管股权投资基金、海盈企业发展、水木投资基金，以及曾昭孔个人。董事长、法定代表人李宗芳 2024-01-15 接任（前任张长海），同时兼党支部书记，公开履历无任何披露、亦不在股东名单中——她的角色是治理与政府关系，不是技术与经营。真正的经营核心是副董事长兼总经理曾昭孔（TAN CHOW KHONG），新加坡籍，曾任 AMD 全球生产营运副总裁、超威半导体技术（中国）有限公司董事总经理，在国际半导体公司逾 20 年，强项正是封装测试的生产运营。团队口径为「多位国际大厂 20 年以上经验的技术博士与管理专家」。\n【与「华封科技」不是一家】池内另有一条「华封科技」（Capcon，2014 年香港成立、新加坡研发，做先进封装 Die Bonder 贴片机，客户台积电、日月光、长电、通富）。两家名字相近、地缘与管理层有交集，但公开股权链条上无法证明同一控制：华封集芯的境外平台是 Pingu Tech Limited，华封科技是 Capcon Limited。业务上是上下游（一个卖贴片机，一个做封测服务），不是母子。\n【估值：未披露，只能粗算】A 轮未公布投前/投后估值。按注册资本变动粗算：A 轮前 50,147.12 万元，A 轮后 53,686.91 万元，新增 3,539.80 万元对应约 6.59% 股权；若 3 亿元全部为增资，投后估值约 45.5 亿元。但若部分为老股转让，实际估值更高。此为推算，未经公司确认，仅作量级参考。\n【风险】① 客户与良率零披露，2.5D 封装最难的恰恰是翘曲控制与桥接对准精度；② 33 亿投资对 5.37 亿注册资本，杠杆极高，23 亿银团的还本付息要靠达产后的现金流，一旦爬坡延后就是财务压力；③ 赛道对手密集——盛合晶微已科创板上市、2.5D 规模量产，长电 XDFOI、通富（绑定 AMD）、甬矽均在扩产，华封集芯是后来者；④ 董事长无公开产业履历且不持股，管理层与股东的利益绑定需另找证据（曾昭孔持股比例、员工持股平台、A 轮业绩承诺均未披露）；⑤ 桥接芯片自研意味着它同时要跟设计公司和封测厂竞争，资源摊薄。\n【观察指标】① 首批量产客户是谁（若是寒武纪、海光、壁仞这类 AI 算力芯片，2.5D 产线才算跑通）；② 单月 Bumping 与 FCBGA 实际产出（对比 14 万片/年、7,200 万颗/年的规划）；③ 桥接芯片是否对外销售（决定它是「方案商」还是「代工厂」）；④ 是否启动新一轮融资及定价（A 轮 45 亿量级能否被验证）；⑤ 与北方华创等国产设备的实际采购关系（33 亿投资里设备占比最大，是国产化的直接观测窗口）。", "listed": false, "funding": [{"inv": "北京高精尖产业发展基金领投；溥泉资本（宁德时代关联）、智微资本（中微半导体关联）、中创聚源基金、广发信德、纳川资本跟投。1 月交割、2 月官宣", "date": "2026-01", "round": "A 轮", "amount": "3 亿元"}, {"inv": "中国农业银行牵头，中国邮政储蓄银行、中国建设银行、中国银行等 7 家金融机构", "date": "2025", "round": "银团贷款（债权）", "amount": "23 亿元"}, {"inv": "亦庄国投、京国瑞投资、北京集成电路产业发展股权投资基金", "date": "2024-06", "round": "政府基金入股", "amount": "未披露"}, {"inv": "水木投资基金普通合伙人有限公司、海盈企业发展有限公司", "date": "2023-09", "round": "天使轮", "amount": "未披露"}], "industry": "semiconductor", "executives": [{"bio": "2024-01-15 接任法定代表人（前任张长海），现任董事长、党支部书记，公开报道中亦以副总经理身份介绍公司经营情况。不在股东名单中，不直接持股。教育背景、前雇主、出生年份等在公开渠道均无披露——这是国资主导项目里职业经理人或委派董事长的典型特征：她承担的是公司治理、党务与政府/园区/国资基金对接，不是技术路线与客户经营。判断这家公司应看总经理曾昭孔与产线良率，而非董事长履历。", "name": "李宗芳", "role": "board", "title": "董事长、法定代表人", "shares": "不持股", "tenure": "2024.1 至今"}, {"bio": "英文名 TAN CHOW KHONG，新加坡籍。曾任 AMD 全球生产营运副总裁、超威半导体技术（中国）有限公司董事总经理，在国际大型半导体公司逾 20 年，主要积累在封装测试的生产运营与全球产能管理。是公司实际经营核心与对外发言代表，行业报道中被视为「真正的灵魂人物」。其个人持股比例未公开。", "name": "曾昭孔", "role": "management", "title": "副董事长、总经理（CEO）", "shares": "个人在股东名单内（比例未披露）", "tenure": "—"}, {"bio": "董事，同时任全资子公司杭州华封集芯电子有限公司法定代表人（2025-07-25 成立，注册资本 500 万元），负责长三角区域板块。", "name": "姚远", "role": "board", "title": "董事", "shares": "—", "tenure": "—"}], "latestTech": "华封桥 2.5D/3D Chiplet 架构；已实现 Bumping→FCBGA/FCCSP→FT 全链条通线量产（2026-09）", "lastFunding": "2026-01", "latestFunding": "2026-01 · A 轮 3 亿元交割（北京高精尖基金领投，溥泉资本、智微资本等跟投）；2025 年获 23 亿元银团贷款", "investorsStructured": [{"date": "2026-01", "kind": "gov", "name": "北京高精尖产业发展基金", "note": "管理人北工投资（北京国资公司全资子公司），在管基金规模超 380 亿元，代表项目含北方华创、中芯北方、京东方、龙芯中科", "role": "lead", "round": "A 轮"}, {"date": "2026-01", "kind": "cvc", "name": "溥泉资本", "note": "宁德时代关联产业基金", "role": "follow", "round": "A 轮"}, {"date": "2026-01", "kind": "cvc", "name": "智微资本", "note": "中微半导体关联基金", "role": "follow", "round": "A 轮"}, {"date": "2024-06", "kind": "gov", "name": "北京集成电路产业发展股权投资基金", "role": "follow", "round": "天使轮/政府基金"}, {"date": "2024-06", "kind": "gov", "name": "北京经济技术开发区产业升级股权投资基金", "note": "亦庄国投体系", "role": "follow", "round": "政府基金"}, {"date": "2024-06", "kind": "gov", "name": "北京京国管股权投资基金", "note": "京国瑞投资体系", "role": "follow", "round": "政府基金"}, {"date": "2023-09", "kind": "vc", "name": "水木投资基金", "role": "follow", "round": "天使轮"}]}'::jsonb,
